head.script:
scwin.trigger1_onclick = function(e) {
    iframe1.setSrc("");
};
scwin.iframe1_oniframeload = function(e) {
    //alert("load");
};
scwin.isBlankPage = function() {
    return WebSquare.wUnit.getJq("#iframe1").contents().find("body").children().length == 0;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("assert", "scwin.isBlankPage()", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    //Function 
